var t=[{title:`Vad bevisen visar`,text:`American Academy of Pediatrics anser att välutformad styrketräning för ungdomar är fördelaktig, med låg skadefrekvens när instruktion och övervakning är bra. Korrekt övervakad styrketräning har inte visat sig hämma längdtillväxt eller skada tillväxtzoner bara för att vikter används.`},{title:`Börja med rörelsegrunderna`,text:`Knäböj med kroppsvikt, armhävningsvarianter, rodd, hopp- och landningsövningar och lätta motståndsövningar lär ut kontroll. Öva symmetriska rörelser och rörelser på ett ben, lär dig hantera utrustningen och gör det svårare utifrån din teknik och mognad, inte utifrån vad dina kompisar lyfter.`},{title:`Hela aktivitetsbilden`,text:`CDC:s vägledning för åldrarna 6–17 rekommenderar minst 60 minuters måttlig till intensiv fysisk aktivitet varje dag, inklusive muskel- och skelettstärkande aktivitet minst tre dagar i veckan. Styrkepass är en del av det, tillsammans med idrott, lek och rekreation.`},{title:`Varför övervakning spelar roll`,text:`Kvalificerad coachning, utrustning som passar din ålder, tillräcklig vila och ett säkert utrymme minskar alla undvikbara risker. Undvik maxförsök utan övervakning och skynda inte på din progression eller ta dig an avancerade lyft på egen hand. Involvera en förälder, vårdnadshavare eller kvalificerad tränare där du kan. Om du har smärta, ett betydande medicinskt tillstånd eller oro för din utveckling, fråga en läkare. Ingen träningsplan kan garantera tillväxt, skadeförebyggande eller prestationsresultat.`}];var a=[{label:`American Academy of Pediatrics: styrketräning för ungdomar`,url:`https://publications.aap.org/pediatrics/article/145/6/e20201010/76942/`},{label:`CDC: fysisk aktivitet för barn och tonåringar`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/children.html`}];var n={sections:t,sources:a};export{n as default,t as sections,a as sources};